pub fn emit(a: &[Rec]) -> i32 {
    let mut rows: Vec<Rec> = a.to_vec();
    rows.sort_by(|x, y| x.kind.cmp(&y.kind));
    let mut out = String::from("issue\tkind\tbody\n");
