pub fn take(text: &str) -> Result<(String, Vec<String>), i32> {
    if text.trim().is_empty() {
        return Err(3);
    }

    let mut kind: Option<String> = None;
    let mut frames = Vec::new();
    let mut raw_frames = 0usize;
    let mut summary = false;

    for line in text.lines() {
        if line.contains("ERROR:") {
            if kind.is_some() || raw_frames != 0 || summary {
                return Err(3);
            }
            let rest = line.split_once("ERROR:").map(|x| x.1).ok_or(3)?.trim();
            let after = rest.strip_prefix("AddressSanitizer:").ok_or(3)?.trim();
            let value = after.split(" on ").next().unwrap_or("").trim();
            if value.is_empty() {
                return Err(3);
            }
            kind = Some(value.to_string());
        } else if line.trim_start().starts_with('#') {
            if kind.is_none() || summary {
                return Err(3);
            }
            let trimmed = line.trim_start();
            let mut words = trimmed.split_whitespace();
            let number = words.next().ok_or(3)?;
            if number.len() < 2 || !number[1..].bytes().all(|b| b.is_ascii_digit()) {
                return Err(3);
            }
            let address = words.next().ok_or(3)?;
            if !address.starts_with("0x") || address.len() <= 2 || !address[2..].bytes().all(|b| b.is_ascii_hexdigit()) {
                return Err(3);
            }
            if words.next() != Some("in") {
                return Err(3);
            }
            let symbol = words.next().ok_or(3)?;
            if symbol.is_empty() {
                return Err(3);
            }
            raw_frames += 1;
            if is_user_frame(symbol) {
                frames.push(fold_hex(symbol));
            }
        } else if line.trim_start().starts_with("SUMMARY:") {
            if kind.is_none() || raw_frames == 0 || summary {
                return Err(3);
            }
            summary = true;
        }
    }

    let kind = kind.ok_or(3)?;
    if raw_frames == 0 || frames.is_empty() || !summary {
        return Err(3);
    }
    Ok((kind, frames))
}

fn is_user_frame(s: &str) -> bool {
    !(s.contains("__asan") || s.contains("__interceptor") || s.contains("__hwasan"))
}

fn fold_hex(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = String::new();
    let mut i = 0usize;
    while i < bytes.len() {
        if i + 2 < bytes.len() && bytes[i] == b'0' && (bytes[i + 1] == b'x' || bytes[i + 1] == b'X') && bytes[i + 2].is_ascii_hexdigit() {
            out.push_str("0xHEX");
            i += 2;
            while i < bytes.len() && bytes[i].is_ascii_hexdigit() {
                i += 1;
            }
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    out
}
